    ChooseAClan(m);
    if (m.cache_size != 0 || m.connecting_state != 0 || m.state != 3 || m.registered != 0) { std::printf("0055fec0_TEST FAIL\n"); return 1; }
    m.has_inventory = true; m.open_menu = 2;
